"""Data models. Every listing has structured fields, so we can filter on them exactly."""
from typing import Literal

from pydantic import BaseModel, Field

PropertyType = Literal["house", "condo", "townhouse"]


class ListingDraft(BaseModel):
    """A listing as generated by the LLM (no id yet)."""

    neighborhood: str = Field(min_length=1)
    property_type: PropertyType
    price: int = Field(gt=0, description="Price in US dollars")
    bedrooms: int = Field(ge=0, le=10)
    bathrooms: float = Field(gt=0, le=10)
    size_sqft: int = Field(gt=100, lt=20_000)
    features: list[str] = Field(description="Short tags, e.g. 'fireplace', 'pool'")
    description: str = Field(min_length=20)
    neighborhood_description: str = Field(min_length=20)


class Listing(ListingDraft):
    """A stored listing with a stable id."""

    id: str

    def to_document(self) -> str:
        """Text that gets embedded for semantic search (one listing = one document)."""
        return (
            f"{self.property_type.title()} in {self.neighborhood}. "
            f"{self.bedrooms} bedrooms, {self.bathrooms} bathrooms, {self.size_sqft} sqft, "
            f"${self.price:,}. Features: {', '.join(self.features)}.\n"
            f"{self.description}\n{self.neighborhood_description}"
        )
